import maya.cmds as cmds
namespace = dwpicker.current_namespace()
if namespace:
    bend_attr_name = '{}:MainExtra2.bendVis'.format(namespace)
else:
    bend_attr_name = 'MainExtra2.bendVis'
if cmds.objExists(bend_attr_name):
    bend_attr = cmds.getAttr(bend_attr_name)
    if bend_attr:
        dwpicker.set_layer_visible('Bend', visible=False)
        cmds.setAttr(bend_attr_name,0)
    else:
        dwpicker.set_layer_visible('Bend', visible=True)
        cmds.setAttr(bend_attr_name,1)
else:
    dwpicker.toggle_layer_visibility('Bend')

import maya.cmds as cmds
namespace = dwpicker.current_namespace()
if namespace:
    attr_name = '{}:visibility_ctrl.faceSecCtrlVis'.format(namespace)
else:
    attr_name = 'visibility_ctrl.faceSecCtrlVis'
if cmds.objExists(attr_name):
    bend_attr = cmds.getAttr(attr_name)
    if bend_attr:
        dwpicker.set_layer_visible('faceSec', visible=False)
        dwpicker.set_layer_visible('faceNoSec', visible=True)
        cmds.setAttr(attr_name,0)
    else:
        dwpicker.set_layer_visible('faceSec', visible=True)
        dwpicker.set_layer_visible('faceNoSec', visible=False)
        cmds.setAttr(attr_name,1)
else:
    dwpicker.toggle_layer_visibility('faceSec')
    dwpicker.toggle_layer_visibility('faceNoSec')
